refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
Функция array_column возвращает значения из одного столбца массива array, который идентифицируется ключом column_key. Необязательный параметр index_key индексирует значения выходного массива значениями столбца index_key входного массива.
Параметр array рассматривается как список строк, каждая из которых сама является массивом или объектом; столбец — это элемент или свойство, которое в каждой строке называет параметр column_key. Строки, не являющиеся ни массивом, ни объектом, а также строки, в которых этот элемент или свойство отсутствует, пропускаются без диагностического сообщения. Ключи параметра array никогда не сохраняются.

&reftitle.returnvalues;

 Функция возвращает массив значений, которые представляют один столбец из входного массива.
 Если в параметре column_key передан &null;, возвращаются сами строки.

  &reftitle.examples;



    Пример получения столбца с именами из набора записей


<?php

// Массив с набором записей, похожих на те, которые возвращает база данных
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);


    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)








     Пример получения столбца с фамилиями из набора записей и индексации фамилий значениями столбца "id"



<?php

// Возьмём массив $records из первого примера
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);


    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)








     Пример получения столбца с именами пользователей из открытого свойства объекта "username"



<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));


    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)








     Пример получения столбца с именами из закрытого свойства объекта "name"
     путём определения магических методов __isset() и __get()



<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));


    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)



   Если магический метод __isset() не определён,
   объект не вносит в возвращаемый массив ни одного элемента.
